css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .bowl { position: absolute; left: 12%; right: 12%; bottom: 4%; height: 26%; border-radius: 6px 6px 42% 42%; background: linear-gradient(color-mix(in srgb, #000 12%, var(--accent-2)), var(--accent-2)); }
.loader .dunk { position: absolute; left: 26%; top: 4%; width: 48%; height: 48%; animation: donut-dip calc(var(--loader-speed) * 2.6) ease-in-out infinite; }
.loader .ring { position: absolute; inset: 0; border-radius: 50%; border: calc(var(--loader-size) * .085) solid var(--accent); }
.loader .glaze { position: absolute; inset: 0; border-radius: 50%; border: calc(var(--loader-size) * .085) solid var(--accent-2); animation: donut-coat calc(var(--loader-speed) * 2.6) ease-in-out infinite; }
@keyframes donut-dip { 0%, 100% { transform: translateY(0); } 40%, 56% { transform: translateY(66%); } }
@keyframes donut-coat { 0%, 30% { clip-path: inset(100% 0 0 0); } 56%, 86% { clip-path: inset(44% 0 0 0); } 98%, 100% { clip-path: inset(100% 0 0 0); } }
